package in.kabadiwala.connect.model; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; @Document("disputes") public class Dispute {@Id public String id; @Indexed public String lotId; public String raisedBy,reason,status="OPEN",resolution; @CreatedDate public Instant createdAt; @LastModifiedDate public Instant updatedAt;}